def main():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()

    for cid, data in EXPANDED_CASES.items():
        tbl = data["tbl"]
        cur.execute(f"""
            UPDATE {tbl}
            SET leitsatz = ?, tenor = ?, tatbestand = ?, gruende = ?
            WHERE case_id = ?
        """, (data["leitsatz"], data["tenor"], data["tatbestand"], data["gruende"], cid))

        chunk_tbl = "chunks" if tbl == "cases" else "reference_chunks"
        chunk_prefix = "CHUNK:CASE:" if tbl == "cases" else "CHUNK:REF_CASE:"
        chunk_id = f"{chunk_prefix}{cid}:0"
        chunk_text = f"[{cid}] | {data['leitsatz']} | {data['tenor']} | {data['tatbestand']} | {data['gruende']}"
        cur.execute(f"""
            UPDATE {chunk_tbl}
            SET text = ?
            WHERE chunk_id = ?
        """, (chunk_text, chunk_id))

        print(f"Updated {cid}: L={len(data['leitsatz'])}, T={len(data['tenor'])}, TB={len(data['tatbestand'])}, G={len(data['gruende'])}")

    conn.commit()
    conn.close()
    print("All 11 cases expanded to meet gold standard!")

if __name__ == '__main__':
    main()
